mod support;
#[path="support/network_suite_reports.rs"] mod network_suite_reports;
use tsrust_compiler::project::{FileSourceProvider,load_project,check_graph};
fn check(source:&str)->Result<String,String>{let directory=support::TempDirectory::new();let path=directory.source(&support::format_round_trip(source));let graph=load_project(&FileSourceProvider,path.to_str().unwrap()).map_err(|error|format!("{error:?}"))?;check_graph(graph).map(|checked|{assert!(checked.warnings().is_empty(),"{:?}",checked.warnings());checked.emit_rust()}).map_err(|error|format!("{error:?}"))}
fn execute(source:&str,expected:&str){let rust=check(source).unwrap();fn safe(tokens:proc_macro2::TokenStream)->bool{tokens.into_iter().all(|token|match token{proc_macro2::TokenTree::Ident(name)=>name!="unsafe",proc_macro2::TokenTree::Group(group)=>safe(group.stream()),_=>true})}assert!(safe(rust.parse().unwrap()));network_suite_reports::assert_registered(source,expected);}
#[test]
fn full_stream_and_split_half_close_examples_execute(){execute(include_str!("../../../examples/network/tcp.tsr"),"ping\n");execute(include_str!("../../../examples/network/tcp-halves.tsr"),"reply after EOF\n");}
#[test]
fn udp_binary_empty_and_remote_endpoint_snapshots_execute(){execute(include_str!("../../../examples/network/udp.tsr"),"5\nhello\n0\n0\n");execute("import {parseAddress,bindUdp,formatAddress} from 'std:net';import {fromArray,at,length} from 'std:bytes';async function main():Task<void>{const bind=unwrap(parseAddress('127.0.0.1:0'));const sender=unwrap(await bindUdp(bind));const receiver=unwrap(await bindUdp(bind));const endpoint=unwrap(receiver.localAddress());unwrap(await sender.sendTo(unwrap(fromArray([0,255,7])),endpoint));const message=unwrap(await receiver.receiveFrom(3));console.log(length(message.data),unwrap(at(message.data,1)),formatAddress(message.remote)===formatAddress(unwrap(sender.localAddress())));receiver.close();sender.close();}","3 255 true\n");}
#[test]
fn full_stream_short_reads_exact_destination_and_getter_aliases(){execute("import {parseAddress,listenTcp,connectTcp,TcpListener,formatAddress} from 'std:net';import {readInto,readExact,writeAll} from 'std:io';import {fromUtf8,alloc,viewMut,toUtf8} from 'std:bytes';async function server(listener:Owned<TcpListener>):Task<void>{const[peer,remote]=unwrap(await listener.accept());listener.close();unwrap(await writeAll(peer,unwrap(fromUtf8('abcd'))));unwrap(await peer.shutdownWrite());peer.close();}async function main():Task<void>{const listen=listenTcp;const connect=connectTcp;const listener=unwrap(await listen(unwrap(parseAddress('127.0.0.1:0'))));const endpoint=unwrap(listener.localAddress());const worker=server(listener).start();try{const client=unwrap(await connect(endpoint));console.log(formatAddress(unwrap(client.peerAddress()))===formatAddress(endpoint),formatAddress(unwrap(client.localAddress())).startsWith('127.0.0.1:'));const destination=unwrap(alloc(4));{const prefix=unwrap(viewMut(destination,0,2));unwrap(await readExact(client,prefix));}{const suffix=unwrap(viewMut(destination,2,4));unwrap(await readExact(client,suffix));}console.log(unwrap(toUtf8(destination)));console.log(unwrap(await readInto(client,unwrap(alloc(1)))));client.close();}catch(failure){worker.cancel();try{await worker;}catch(cleanupFailure){}throw failure;}await worker;}","true true\nabcd\n0\n");}
#[test]
fn copy_supports_memory_reader_to_full_stream(){execute("import {parseAddress,listenTcp,connectTcp,TcpListener} from 'std:net';import {reader,readAll,copy,close} from 'std:io';import {fromUtf8,toUtf8} from 'std:bytes';async function server(listener:Owned<TcpListener>):Task<string>{const[peer,remote]=unwrap(await listener.accept());listener.close();const text=unwrap(toUtf8(unwrap(await readAll(peer))));peer.close();return text;}async function main():Task<void>{const listener=unwrap(await listenTcp(unwrap(parseAddress('127.0.0.1:0'))));const endpoint=unwrap(listener.localAddress());const worker=server(listener).start();try{const client=unwrap(await connectTcp(endpoint));const input=reader(unwrap(fromUtf8('copy bytes')));console.log(unwrap(await copy(input,client,3)));unwrap(await close(input));unwrap(await client.shutdownWrite());client.close();}catch(failure){worker.cancel();try{await worker;}catch(cleanupFailure){}throw failure;}console.log(await worker);}","10\ncopy bytes\n");}
#[test]
fn pending_full_stream_listener_and_udp_loans_reject_transfer(){
 let prefix="import {TcpStream,parseAddress,listenTcp,connectTcp} from 'std:net';import {readInto,copy} from 'std:io';import {alloc,set} from 'std:bytes';async function inspect(stream:Mutable<TcpStream>):Task<void>{const bytes=unwrap(alloc(3));const pending=readInto(stream,bytes);";
 assert!(check(&format!("{prefix}unwrap(set(bytes,0,1));unwrap(await pending);}}function main(){{}}")).is_err());
 assert!(check(&format!("{prefix}stream.split();unwrap(await pending);}}function main(){{}}")).is_err());
 assert!(check("import {TcpStream} from 'std:net';import {copy} from 'std:io';async function inspect(stream:Mutable<TcpStream>):Task<void>{unwrap(await copy(stream,stream));}function main(){}").is_err());
 assert!(check("import {TcpListener} from 'std:net';async function inspect(listener:Owned<TcpListener>):Task<void>{const task=listener.accept();listener.close();await task;}function main(){}").is_err());
 assert!(check("import {UdpSocket,SocketAddress} from 'std:net';import {Bytes,set} from 'std:bytes';async function inspect(socket:Owned<UdpSocket>,data:Owned<Bytes>,address:ReadOnly<SocketAddress>):Task<void>{const task=socket.sendTo(data,address);unwrap(set(data,0,1));await task;}function main(){}").is_err());
 assert!(check("import {UdpSocket} from 'std:net';async function inspect(socket:Owned<UdpSocket>):Task<void>{const task=socket.receiveFrom(1);socket.close();await task;}function main(){}").is_err());
}
#[test]
fn full_stream_resource_cannot_clone_or_enter_consuming_reader_adapters(){for source in ["import {TcpStream} from 'std:net';function inspect(stream:Owned<TcpStream>){const duplicate=clone(stream);}function main(){}","import {TcpStream} from 'std:net';import {lines,close} from 'std:io';function inspect(stream:Owned<TcpStream>){lines(stream);}function main(){}"]{assert!(check(source).is_err());}}
#[test]
fn transport_catalog_examples_cover_every_public_method(){let catalog:serde_json::Value=serde_json::from_str(include_str!("../../tsrust-lsp/src/builtins.json")).unwrap();let mut seen=std::collections::HashSet::new();for group in ["TcpListener","TcpStream","UdpSocket"]{for entry in catalog[group].as_array().unwrap(){assert!(!entry["examples"].as_array().unwrap().is_empty());for example in entry["examples"].as_array().unwrap(){let source=example["source"].as_str().unwrap();if seen.insert(source.to_owned()){execute(source,example["output"].as_str().unwrap());}}}}}

#[test]
fn tcp_copy_to_full_stream_and_owned_writer_half(){
 for half in [false,true]{let transfer=if half{"const[unused,output]=outgoing.split();unwrap(await close(unused));unwrap(await copy(incoming,output,3));unwrap(await close(output));"}else{"unwrap(await copy(incoming,outgoing,3));unwrap(await outgoing.shutdownWrite());outgoing.close();"};let source=format!("import {{parseAddress,listenTcp,connectTcp,TcpListener}} from 'std:net';import {{readAll,writeAll,copy,close}} from 'std:io';import {{fromUtf8,toUtf8}} from 'std:bytes';async function server(listener:Owned<TcpListener>):Task<void>{{const[incoming,from]=unwrap(await listener.accept());const[outgoing,to]=unwrap(await listener.accept());listener.close();{transfer}incoming.close();}}async function main():Task<void>{{const listener=unwrap(await listenTcp(unwrap(parseAddress('127.0.0.1:0'))));const endpoint=unwrap(listener.localAddress());const worker=server(listener).start();try{{const source=unwrap(await connectTcp(endpoint));const destination=unwrap(await connectTcp(endpoint));unwrap(await writeAll(source,unwrap(fromUtf8('forward'))));unwrap(await source.shutdownWrite());console.log(unwrap(toUtf8(unwrap(await readAll(destination)))));source.close();destination.close();}}catch(failure){{worker.cancel();try{{await worker;}}catch(cleanupFailure){{}}throw failure;}}await worker;}}");execute(&source,"forward\n");}
}
#[test]
fn network_socket_package_relocates_and_builds_offline(){let directory=support::TempDirectory::new();let input=directory.source(&support::format_round_trip(include_str!("../../../examples/network/tcp.tsr")));let package=directory.0.join("package");support::success(&support::run(support::cli().arg("emit").arg(&input).arg("--package").arg("-o").arg(&package),60));let rust=std::fs::read_to_string(package.join("src/main.rs")).unwrap();std::fs::write(package.join("src/main.rs"),format!("#![forbid(unsafe_code)]\n{rust}")).unwrap();std::fs::remove_file(input).unwrap();let relocated=directory.0.join("relocated");std::fs::rename(package,&relocated).unwrap();let home=directory.0.join("empty-cargo-home");std::fs::create_dir(&home).unwrap();let target=std::env::var_os("CARGO_TARGET_DIR").map(std::path::PathBuf::from).unwrap_or_else(||std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../target"));let mut build=std::process::Command::new("rustup");build.args(["run",tsrust_compiler::RUST_BACKEND_VERSION,"cargo","build","--offline","--locked"]).current_dir(&relocated).env("CARGO_HOME",home).env("CARGO_INCREMENTAL","0").env("CARGO_BUILD_JOBS","1").env("CARGO_TARGET_DIR",&target);support::success(&support::run(&mut build,300));let output=support::run(std::process::Command::new(target.join(format!("debug/program{}",std::env::consts::EXE_SUFFIX))).current_dir(&relocated),30);support::success(&output);assert_eq!(output.stdout,b"ping\n");}

#[test]
fn handler_owner_move_before_rethrow_preserves_normal_continuation(){execute("import {alloc,length,Bytes} from 'std:bytes';function consume(value:Owned<Bytes>):void{console.log(length(value));}function inspect(fail:boolean):void{const owner=unwrap(alloc(3));try{if(fail){throw 1;}}catch(error){consume(owner);throw error;}consume(owner);}function main(){inspect(false);try{inspect(true);}catch(error){console.log(error);}}","3\n3\n1\n");}

#[test]
fn registered_network_runtime_programs_share_one_profiled_runner(){network_suite_reports::execute();}
